file.content:
                f"wallet {wallet_id!r} sign session {session_id!r} signed "
                "without both stored shares"
            )
        rebuilt["state"] = "signed"
        rebuilt["aggregate_signature"] = (
            self._aggregate_session_shares(rebuilt).hex()
        )
        # 记录带有聚合签名时，重算结果必须一致（被篡改即 fail-closed）；
        # 记录恰缺聚合签名（signed 已提交、状态写盘不完整的崩溃现场）
        # 时按事件前滚补齐即可。
        recorded_aggregate = record.get("aggregate_signature")
        if (
            isinstance(recorded_aggregate, str)
            and recorded_aggregate != rebuilt["aggregate_signature"]
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} sign session {session_id!r} "
                "aggregate signature does not recompute to the record"
            )
    elif terminal == "expired":
        # collecting 与 ready 到点均可过期：终态不再聚合。
        rebuilt["state"] = "expired"
    else:
        # 轮换迁移后的非终态：旧份额已剔除，按当前快照内已提交份数恢复
        rebuilt["state"] = (
            "ready" if len(rebuilt["shares"]) == 2 else "collecting"
        )

    if rebuilt != record:
        self._store.update_sign_session(
            wallet_id, session_id, rebuilt
        )

# -- 可恢复两方 DKG ------------------------------------------------------

@staticmethod
def _validate_dkg_id(dkg_id: object) -> None:
    if not isinstance(dkg_id, str) or not ROTATION_ID_RE.match(dkg_id):
        raise ServiceError(
            400, "dkg id must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _validate_dkg_node(node: object) -> None:
    if not isinstance(node, str) or not ROTATION_ID_RE.match(node):
        raise ServiceError(
            400, "node must match [A-Za-z0-9_-]{1,128}"
        )

@staticmethod
def _dkg_state(
    nodes: list, commits: dict, shared: dict
) -> str:
    """由已推进的注册/承诺/份额确认计数推导会话阶段。"""
    if len(shared) == 2:
        return "done"
    if len(commits) == 2:
        return "share"
    if len(nodes) == 2:
        return "commit"
    return "register"

@staticmethod
def _dkg_view(session: dict, round_no: int) -> dict:
    """DKG 会话某一轮的对外视图（GET/POST/failover 同形，键序固定）。

    三个数组均按注册序；完成公钥为两份注册 key 按注册序拼接，
    非 done 为 null。视图只含标识/轮次/公钥/哈希，绝不含私钥
    或份额正文。"""
    round_state = session["rounds"][round_no]
    nodes = round_state["nodes"]
    public_key = None
    if round_state["state"] == "done":
        public_key = nodes[0][1] + nodes[1][1]
    return {
        "id": session["id"],
        "round": round_no,
        "state": round_state["state"],
        "nodes": [node for node, _ in nodes],
        "committed": [
            node for node, _ in nodes if node in round_state["commits"]
        ],
        "shared": [
            node for node, _ in nodes if node in round_state["shared"]
        ],
        "public_key": public_key,
    }

@staticmethod
def _parse_dkg_request_id(
    wallet_id: str, request_id: str, failover: bool
) -> tuple[str, int]:
    """把 DKG 事件的 request_id 解析为 (会话 id, 轮次)。

    基线轮（第 1 轮）的 request_id 即会话 id 本身；派生轮（第 R≥2
    轮）为 ``<会话id>/<R>``。dkg_failover 事件必须指向派生轮；
    dkg_stage 事件的轮次后缀不得为 1（基线轮无后缀）。任何畸形
    （空段、多斜杠、非规范轮次、非法会话 id）都不可对账。"""
    parts = request_id.split("/")
    round_no = 1
    if len(parts) == 1:
        if failover:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg_failover event whose "
                "request_id does not name a derived round"
            )
        dkg_id = parts[0]
    elif len(parts) == 2:
        dkg_id, suffix = parts
        if (
            not suffix.isascii()
            or not suffix.isdigit()
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg event with a "
                "malformed round suffix"
            )
        try:
            round_no = int(suffix)
        except ValueError:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg event with a "
                "malformed round suffix"
            )
        if round_no < 1 or str(round_no) != suffix:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg event with a "
                "non-canonical round suffix"
            )
        if failover:
            if round_no < 2:
                raise RecoveryError(
                    f"wallet {wallet_id!r} has a dkg_failover event "
                    "for the baseline round"
                )
        elif round_no == 1:
            raise RecoveryError(
                f"wallet {wallet_id!r} has a dkg_stage event whose "
                "round suffix names the baseline round"
            )
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} has a dkg event with a malformed "
            "request_id"
        )
    if not ROTATION_ID_RE.match(dkg_id):
        raise RecoveryError(
            f"wallet {wallet_id!r} has a dkg event with a "
            "malformed session id"
        )
    return dkg_id, round_no

def _dkg_sessions(self, wallet_id: str) -> dict[str, dict]:
    """从 dkg_stage / dkg_failover 事件重建并严格校验该钱包全部 DKG 会话。

    事件是 DKG 状态的唯一持久化与提交点：基线轮（第 1 轮）由
    request_id 为会话 id 的 dkg_stage 事件重放；每个派生轮（第
    R≥2 轮）由 request_id 为 ``<id>/<R>`` 的唯一 dkg_failover 事件
    从上一轮派生，再由同 request_id 的 dkg_stage 事件推进。任何矛盾
    （形状、字段约束、轮次缺口/重复、阶段顺序、承诺不一致、
    details.state 与重算不符）都抛 RecoveryError（fail-closed：
    常驻 503、serve 拒绝就绪），绝不静默跳过或任取一条。纯只读，
    不分配 seq、不写任何状态。"""
    stage_rounds: dict[str, dict[int, list[dict]]] = {}
    for request_id, events in self._audit.dkg_stage_events(
        wallet_id
    ).items():
        dkg_id, round_no = self._parse_dkg_request_id(
            wallet_id, request_id, failover=False
        )
        stage_rounds.setdefault(dkg_id, {}).setdefault(
            round_no, []
        ).extend(events)
    failover_rounds: dict[str, dict[int, list[dict]]] = {}
    for request_id, events in self._audit.dkg_failover_events(
        wallet_id
    ).items():
        dkg_id, round_no = self._parse_dkg_request_id(
            wallet_id, request_id, failover=True
        )
        failover_rounds.setdefault(dkg_id, {}).setdefault(
            round_no, []
        ).extend(events)
    sessions: dict[str, dict] = {}
    for dkg_id in sorted(set(stage_rounds) | set(failover_rounds)):
        sessions[dkg_id] = self._rebuild_dkg_session(
            wallet_id,
            dkg_id,
            stage_rounds.get(dkg_id, {}),
            failover_rounds.get(dkg_id, {}),
        )
    return sessions

def _rebuild_dkg_session(
    self,
    wallet_id: str,
    dkg_id: str,
    stage_rounds: dict[int, list[dict]],
    failover_rounds: dict[int, list[dict]],
) -> dict:
    """按轮次链重建某 DKG 会话并严格校验。

    轮次链必须连续：基线轮（第 1 轮）必有 dkg_stage 事件；第 R≥2
    轮必有且仅有一条 dkg_failover 事件从第 R-1 轮派生。派生轮不
    接受 register，aborted 轮不接受任何阶段事件。"""
    baseline_events = stage_rounds.get(1, [])
    if not baseline_events:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has no "
            "baseline round events"
        )
    rounds: dict[int, dict] = {
        1: self._replay_dkg_round(
            wallet_id, dkg_id, 1, baseline_events, seed=None
        )
    }
    failovers: dict[int, dict] = {}
    derived = [r for r in stage_rounds if r >= 2]
    max_round = max([1, *failover_rounds, *derived])
    for round_no in range(2, max_round + 1):
        events = failover_rounds.get(round_no, [])
        if len(events) != 1:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} round "
                f"{round_no} does not have exactly one dkg_failover "
                "event"
            )
        new_round, committed = self._apply_dkg_failover(
            wallet_id, dkg_id, round_no, events[0], rounds[round_no - 1]
        )
        failovers[round_no] = committed
        rounds[round_no] = self._replay_dkg_round(
            wallet_id,
            dkg_id,
            round_no,
            stage_rounds.get(round_no, []),
            seed=new_round,
        )
    return {
        "id": dkg_id,
        "rounds": rounds,
        "current": max_round,
        "failovers": failovers,
    }

def _apply_dkg_failover(
    self,
    wallet_id: str,
    dkg_id: str,
    round_no: int,
    event: dict,
    prev_round: dict,
) -> tuple[dict, dict]:
    """校验一条 dkg_failover 事件并从上一轮派生新轮次。

    返回 (新轮次状态, 已提交参数)。abort 仅限非终态轮、后三值
    （node/replacement/key）必须为 null，派生出 aborted 空轮；
    replace 仅限两方已注册的 commit|share 轮，key 为 64 位小写
    hex、node 在用、replacement 空闲，换槽并清空后两数组后回到
    commit。任何矛盾都抛 RecoveryError。"""
    if (
        event.get("actor_id") is not None
        or event.get("reason") is not None
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
            "dkg_failover event with actor/reason set"
        )
    details = event.get("details")
    if not isinstance(details, dict) or set(details) != {
        "id",
        "round",
        "action",
        "node",
        "replacement",
        "key",
        "state",
    }:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
            "malformed dkg_failover event"
        )
    if details["id"] != dkg_id:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg_failover event id does not "
            "match its request_id"
        )
    recorded_round = details["round"]
    if (
        not isinstance(recorded_round, int)
        or isinstance(recorded_round, bool)
        or recorded_round != round_no
    ):
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg_failover event round does not "
            "match its request_id"
        )
    action = details["action"]
    node = details["node"]
    replacement = details["replacement"]
    key = details["key"]
    prev_state = prev_round["state"]
    committed = {
        "action": action,
        "node": node,
        "replacement": replacement,
        "key": key,
    }
    if action == "abort":
        if (
            node is not None
            or replacement is not None
            or key is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed abort failover event"
            )
        if prev_state in ("done", "aborted"):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} aborts "
                "a terminal round"
            )
        if details["state"] != "aborted":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} "
                "failover state does not match the aborted round"
            )
        new_round = {
            "round": round_no,
            "nodes": [],
            "commits": {},
            "shared": {},
            "state": "aborted",
        }
    elif action == "replace":
        if not _is_lower_hex_32(key):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replace failover key"
            )
        if not isinstance(node, str) or not ROTATION_ID_RE.match(node):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replace failover node"
            )
        if (
            not isinstance(replacement, str)
            or not ROTATION_ID_RE.match(replacement)
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed replace failover replacement"
            )
        if prev_state not in ("commit", "share"):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replaces "
                "a node outside the commit/share stage"
            )
        node_ids = [n for n, _ in prev_round["nodes"]]
        if node not in node_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replaces "
                "a node that is not active"
            )
        if replacement in node_ids:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} replaces "
                "with a node that is not free"
            )
        new_nodes = [
            (replacement, key) if n == node else (n, k)
            for n, k in prev_round["nodes"]
        ]
        if details["state"] != "commit":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} "
                "failover state does not match the replaced round"
            )
        new_round = {
            "round": round_no,
            "nodes": new_nodes,
            "commits": {},
            "shared": {},
            "state": "commit",
        }
    else:
        raise RecoveryError(
            f"wallet {wallet_id!r} dkg session {dkg_id!r} has an "
            "unknown failover action"
        )
    return new_round, committed

def _replay_dkg_round(
    self,
    wallet_id: str,
    dkg_id: str,
    round_no: int,
    events: list[dict],
    seed: dict | None,
) -> dict:
    """按 seq 升序重放某轮次的 dkg_stage 事件并严格校验。

    seed 为 None 时是基线轮（允许 register 建立两方）；否则为故障
    派生轮（节点槽位已由 dkg_failover 确定，不接受 register；
    aborted 轮不接受任何阶段事件）。"""
    if seed is None:
        nodes: list[tuple[str, str]] = []
        commits: dict[str, str] = {}
        shared: dict[str, tuple[str, str]] = {}
    else:
        if events and seed["state"] == "aborted":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has "
                "stage events on an aborted round"
            )
        nodes = list(seed["nodes"])
        commits = dict(seed["commits"])
        shared = dict(seed["shared"])
    for event in events:
        if (
            event.get("actor_id") is not None
            or event.get("reason") is not None
        ):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "dkg_stage event with actor/reason set"
            )
        details = event.get("details")
        if not isinstance(details, dict) or set(details) != {
            "id",
            "op",
            "node",
            "key",
            "hash",
            "peer",
            "state",
        }:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed dkg_stage event"
            )
        if details["id"] != dkg_id:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg_stage event id does not "
                "match its request_id"
            )
        op = details["op"]
        node = details["node"]
        key = details["key"]
        hash_value = details["hash"]
        peer = details["peer"]
        if op not in DKG_OPS:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has an "
                "unknown op"
            )
        if seed is not None and op == "register":
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "register event on a derived round"
            )
        if not isinstance(node, str) or not ROTATION_ID_RE.match(node):
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                "malformed node"
            )
        node_ids = [n for n, _ in nodes]
        if op == "register":
            if (
                not _is_lower_hex_32(key)
                or hash_value is not None
                or peer is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "malformed register event"
                )
            if node in node_ids or len(nodes) == 2:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "contradictory register sequence"
                )
            nodes.append((node, key))
        elif op == "commit":
            if (
                key is not None
                or not _is_lower_hex_32(hash_value)
                or peer is not None
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "malformed commit event"
                )
            if (
                len(nodes) != 2
                or node not in node_ids
                or node in commits
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "contradictory commit sequence"
                )
            commits[node] = hash_value
        else:  # share
            if (
                key is not None
                or not _is_lower_hex_32(hash_value)
                or not isinstance(peer, str)
                or not ROTATION_ID_RE.match(peer)
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "malformed share event"
                )
            if (
                len(nodes) != 2
                or len(commits) != 2
                or node not in node_ids
                or node in shared
            ):
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} has a "
                    "contradictory share sequence"
                )
            if peer == node or peer not in node_ids:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} share "
                    "event has an invalid peer"
                )
            if commits[peer] != hash_value:
                raise RecoveryError(
                    f"wallet {wallet_id!r} dkg session {dkg_id!r} share "
                    "hash does not match the peer commitment"
                )
            shared[node] = (hash_value, peer)
        state = self._dkg_state(nodes, commits, shared)
        if details["state"] != state:
            raise RecoveryError(
                f"wallet {wallet_id!r} dkg session {dkg_id!r} event "
                "state does not match the replayed stage"
            )
    if seed is not None and seed["state"] == "aborted":
        state = "aborted"
    else:
        state = self._dkg_state(nodes, commits, shared)
    return {
        "round": round_no,
        "nodes": nodes,
        "commits": commits,
        "shared": shared,
        "state": state,
    }

@staticmethod
def _parse_round_param(round_param: object) -> int:
    """解析 ?round= 查询参数：须为规范十进制正整数，否则 400。"""
    if (
        not isinstance(round_param, str)
        or not round_param.isascii()
        or not round_param.isdigit()
    ):
        raise ServiceError(400, "round must be a positive integer")
    try:
        round_no = int(round_param)
    except ValueError:
        raise ServiceError(400, "round must be a positive integer")
    if round_no < 1 or str(round_no) != round_param:
        raise ServiceError(400, "round must be a positive integer")
    return round_no

def _resolve_dkg_round(
    self, session: dict | None, round_param: object
) -> int:
    """把 ?round= 参数解析为要操作的轮次号。

    无任何故障轮次时 P 无需参照轮次（行为与旧版一致，显式
    ?round=1 亦接受）；存在故障轮次后必须显式给出当前轮：缺参
    409、旧轮 409、未知轮 404、非法参数 400。"""
    requested = (
        self._parse_round_param(round_param)
        if round_param is not None
        else None
    )
    if session is None:
        # 会话尚不存在：仅 register 可经第 1 轮创建
        if requested is None or requested == 1:
            return 1
        raise ServiceError(404, f"round {requested} not found")
    current = session["current"]
    if requested is None:
        if current > 1:
            raise ServiceError(
                409, "round query parameter is required"
            )
        return 1
    if requested > current:
        raise ServiceError(404, f"round {requested} not found")
    if requested < current:
        raise ServiceError(
            409, f"round {requested} is not the current round"
        )
    return requested

def get_dkg_session(
    self, wallet_id: str, dkg_id: str, round_param: object = None
) -> dict:
    """查询 DKG 会话当前轮视图；钱包/会话未知 404，dkg id 非法 400。

    存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
    404、非法 400）；aborted 轮一律 409。"""
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            session = self._dkg_sessions(wallet_id).get(dkg_id)
            if session is None:
                raise ServiceError(
                    404, f"dkg session {dkg_id!r} not found"
                )
            round_no = self._resolve_dkg_round(session, round_param)
            if session["rounds"][round_no]["state"] == "aborted":
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            return self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def post_dkg_stage(
    self,
    wallet_id: str,
    dkg_id: object,
    op: object,
    node: object,
    key: object,
    hash_value: object,
    peer: object,
    round_param: object = None,
) -> tuple[int, dict]:
    """推进两方 DKG 会话当前轮一个阶段，返回 (状态码, 会话视图)。

    - 钱包未知 404；非 register 的未知会话 404；参数非法 400；
    - 首提 201；同值重放 200（优先于阶段判定）；异值/错阶段/第三
      节点 409；
    - 双方依序推进 register→commit→share→done：register 仅 key
      非 null（64 位小写 hex），commit 仅 hash 非 null（64 位小写
      sha256），share 仅 hash/peer 非 null 且 hash 等于 peer 承诺
      （份额链下交换，后端不收正文）；
    - 存在故障轮次后必须带 ?round= 当前轮（缺参/旧轮 409、未知轮
      404、非法 400）；aborted 轮一律 409；派生轮不接受 register，
      commit/share 沿用旧约；
    - dkg_stage 事件（request_id 为会话 id 或 ``<id>/<轮次>``，
      details 依次 id,op,node,key,hash,peer,state，未用值 null）
      是唯一持久化与提交点：首提在跨进程事务锁内追加，重放不记；
      事件之外不写任何状态，崩溃后由事件序列重建。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            if op not in DKG_OPS:
                raise ServiceError(
                    400,
                    "op must be one of " + ", ".join(DKG_OPS),
                )
            self._validate_dkg_node(node)
            if op == "register":
                if not _is_lower_hex_32(key):
                    raise ServiceError(
                        400, "key must be 64 lowercase hex characters"
                    )
                if hash_value is not None or peer is not None:
                    raise ServiceError(
                        400, "register accepts only a non-null key"
                    )
            elif op == "commit":
                if not _is_lower_hex_32(hash_value):
                    raise ServiceError(
                        400, "hash must be 64 lowercase hex characters"
                    )
                if key is not None or peer is not None:
                    raise ServiceError(
                        400, "commit accepts only a non-null hash"
                    )
            else:  # share
                if not _is_lower_hex_32(hash_value):
                    raise ServiceError(
                        400, "hash must be 64 lowercase hex characters"
                    )
                if key is not None:

                    raise ServiceError(
                        400, "share accepts only non-null hash and peer"
                    )
                self._validate_dkg_node(peer)
            sessions = self._dkg_sessions(wallet_id)
            session = sessions.get(dkg_id)
            if session is None:
                if op != "register":
                    # 非 register 的未知流程 404
                    raise ServiceError(
                        404, f"dkg session {dkg_id!r} not found"
                    )
                round_no = self._resolve_dkg_round(None, round_param)
                session = {
                    "id": dkg_id,
                    "rounds": {
                        1: {
                            "round": 1,
                            "nodes": [],
                            "commits": {},
                            "shared": {},
                            "state": "register",
                        }
                    },
                    "current": 1,
                    "failovers": {},
                }
            else:
                round_no = self._resolve_dkg_round(session, round_param)
            round_state = session["rounds"][round_no]
            if round_state["state"] == "aborted":
                # aborted 轮一律 409
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} is "
                    "aborted",
                )
            if round_no >= 2 and op == "register":
                # 派生轮的节点槽位由故障轮次确定，不接受 register
                raise ServiceError(
                    409,
                    f"dkg session {dkg_id!r} round {round_no} does "
                    "not accept register",
                )
            if op == "register":
                registered = dict(round_state["nodes"])
                if node in registered:
                    # 同值重放 200 优先；异值 409
                    if registered[node] != key:
                        raise ServiceError(
                            409,
                            f"node {node!r} already registered a "
                            "different key",
                        )
                    return 200, self._dkg_view(session, round_no)
                if len(round_state["nodes"]) >= 2:
                    # 已有两方后的新注册即第三节点
                    raise ServiceError(
                        409,
                        f"dkg session {dkg_id!r} already has "
                        "two nodes",
                    )
            else:
                node_ids = [n for n, _ in round_state["nodes"]]
                if op == "commit":
                    if node in round_state["commits"]:
                        # 同值重放 200 优先；异值 409
                        if round_state["commits"][node] != hash_value:
                            raise ServiceError(
                                409,
                                f"node {node!r} already committed a "
                                "different hash",
                            )
                        return 200, self._dkg_view(session, round_no)
                    if node not in node_ids:
                        raise ServiceError(
                            409, f"node {node!r} is not a participant"
                        )
                    if round_state["state"] != "commit":
                        raise ServiceError(
                            409,
                            f"dkg session {dkg_id!r} is not in the "
                            "commit stage",
                        )
                else:  # share
                    if node in round_state["shared"]:
                        # 同值重放 200 优先；异值 409
                        if round_state["shared"][node] != (
                            hash_value,
                            peer,
                        ):
                            raise ServiceError(
                                409,
                                f"node {node!r} already shared with "
                                "different parameters",
                            )
                        return 200, self._dkg_view(session, round_no)
                    if node not in node_ids:
                        raise ServiceError(
                            409, f"node {node!r} is not a participant"
                        )
                    if round_state["state"] != "share":
                        raise ServiceError(
                            409,
                            f"dkg session {dkg_id!r} is not in the "
                            "share stage",
                        )
                    if peer == node or peer not in node_ids:
                        raise ServiceError(
                            409, f"peer {peer!r} is not the other node"
                        )
                    if round_state["commits"][peer] != hash_value:
                        raise ServiceError(
                            409,
                            "hash does not match the peer commitment",
                        )
            # 首次提交：应用阶段推进并以 dkg_stage 事件为唯一提交点
            # （在跨进程事务锁内追加；事件之外无任何状态落盘，崩溃后
            # 由事件序列重建，无需回滚）。
            if op == "register":
                round_state["nodes"].append((node, key))
            elif op == "commit":
                round_state["commits"][node] = hash_value
            else:
                round_state["shared"][node] = (hash_value, peer)
            round_state["state"] = self._dkg_state(
                round_state["nodes"],
                round_state["commits"],
                round_state["shared"],
            )
            request_id = (
                dkg_id if round_no == 1 else f"{dkg_id}/{round_no}"
            )
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_DKG_STAGE,
                    request_id=request_id,
                    details={
                        "id": dkg_id,
                        "op": op,
                        "node": node,
                        "key": key,
                        "hash": hash_value,
                        "peer": peer,
                        "state": round_state["state"],
                    },
                ),
            )
            return 201, self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

def post_dkg_failover(
    self,
    wallet_id: str,
    dkg_id: object,
    round_no: object,
    action: object,
    node: object,
    replacement: object,
    key: object,
    approval_request_id: object = _NO_APPROVAL,
) -> tuple[int, dict]:
    """为两方 DKG 会话提交一个故障轮次，返回 (状态码, 新轮视图)。

    - 钱包/会话未知 404；参数非法 400；
    - 首轮故障基于基线轮，后续基于当前轮：round 必须恰为当前轮 +1；
    - 首提 201；同参重放 200（优先于状态判定）；异参 409；
    - abort 仅限非终态轮，node/replacement/key 必须全为 null，
      派生轮为 aborted 且三数组为空；replace 仅限两方已注册的
      commit|share 轮，key 为 64 位小写 hex、node 在用、
      replacement 空闲，换槽并清空 committed/shared 后回到 commit；
    - 故障审批策略（仅由 dkg_failover_policy_updated 事件恢复，缺省
      关闭）：禁用时沿用旧五键；启用时恰收旧五键及安全标识
      approval_request_id，该单须为同钱包既有且 approved 的审批单，
      message 逐字为既定紧凑 JSON（轮次即本次 round）。未知/挂起/
      拒绝/过期/非 approved、message 不符或轮次已变化均 409 且
      DKG 状态不变；已提交故障的旧五键同参重放优先 200、不复查
      审批；
    - dkg_failover 事件（request_id 为 ``<id>/<轮次>``，details
      依次 id,round,action,node,replacement,key,state，不含审批
      标识）是唯一持久化与提交点：首提在跨进程事务锁内追加，重放
      不记；事件之外不写任何状态，崩溃后由事件序列重建。
    """
    try:
        with self._wallet_lock(wallet_id):
            self._heal_wallet(wallet_id)
            # 404 优先于 400：锁内先判定钱包存在性
            self._get_wallet_or_404(wallet_id)
            self._validate_dkg_id(dkg_id)
            if (
                not isinstance(round_no, int)
                or isinstance(round_no, bool)
                or round_no < 1
            ):
                raise ServiceError(
                    400, "round must be a positive integer"
                )
            if action not in DKG_FAILOVER_ACTIONS:
                raise ServiceError(
                    400,
                    "action must be one of "
                    + ", ".join(DKG_FAILOVER_ACTIONS),
                )
            if action == "abort":
                if (
                    node is not None
                    or replacement is not None
                    or key is not None
                ):
                    raise ServiceError(
                        400,
                        "abort accepts only null node, replacement "
                        "and key",
                    )
            else:  # replace
                self._validate_dkg_node(node)
                self._validate_dkg_node(replacement)
                if not _is_lower_hex_32(key):
                    raise ServiceError(
                        400, "key must be 64 lowercase hex characters"
                    )
            approval_required = self._dkg_failover_policy_enabled(
                wallet_id
            )
            sessions = self._dkg_sessions(wallet_id)
            session = sessions.get(dkg_id)
            if session is None:
                raise ServiceError(
                    404, f"dkg session {dkg_id!r} not found"
                )
            # 已提交故障轮次的同参重放优先 200 且不复查（不复查审批
            # 开关、approval_request_id 与审批单现状）；异参 409。
            # 重放只比对旧五键，approval_request_id 不参与：禁用/启用
            # 策略切换、审批单事后终态化都不影响已提交故障的幂等重放。
            committed = session["failovers"].get(round_no)
            if committed is not None:
                if (
                    committed["action"] == action
                    and committed["node"] == node
                    and committed["replacement"] == replacement
                    and committed["key"] == key
                ):
                    return 200, self._dkg_view(session, round_no)
                raise ServiceError(
                    409,
                    f"round {round_no} already failed over with "
                    "different parameters",
                )
            # 首提路径才按当前策略校验请求体键集：启用时恰收六键
            # （approval_request_id 为安全标识）；禁用时沿用旧五键。
            if approval_required:
                if (
                    not isinstance(approval_request_id, str)
                    or not ROTATION_ID_RE.match(approval_request_id)
                ):
                    raise ServiceError(
                        400,
                        "approval_request_id must match "
                        "[A-Za-z0-9_-]{1,128}",
                    )
            elif approval_request_id is not self._NO_APPROVAL:
                raise ServiceError(
                    400,
                    "body must contain exactly round, action, node, "
                    "replacement and key",
                )
            current = session["current"]
            if approval_required:
                # 审批门控（sign-requests 契约：可能懒过期并原子记一次
                # request_expired）：未知/挂起/拒绝/过期/非 approved、
                # message 不符或轮次已变化均 409，且不落事件、不改 DKG
                # 现场。
                try:
                    approval_record = self._store.get_request(
                        wallet_id, approval_request_id
                    )
                except ValueError:
                    raise ServiceError(
                        400, "invalid approval_request_id"
                    )
                if approval_record is None:
                    raise ServiceError(
                        409,
                        f"approval request {approval_request_id!r} "
                        "not found",
                    )
                approval_record = self._expire_if_needed(
                    wallet_id, approval_record
                )
                expected_message = self._dkg_failover_approval_message(
                    dkg_id, round_no, action, node, replacement, key
                )
                if approval_record["message"] != expected_message:
                    raise ServiceError(
                        409,
                        "approval request message does not match this "
                        "failover",
                    )
                if approval_record["state"] != "approved":
                    raise ServiceError(
                        409,
                        f"approval request {approval_request_id!r} is "
                        f"{approval_record['state']}, not approved",
                    )
            if round_no != current + 1:
                # 审批通过但轮次已变化：409 且不变
                raise ServiceError(
                    409, f"round must be {current + 1}"
                )
            current_round = session["rounds"][current]
            state = current_round["state"]
            if action == "abort":
                if state in ("done", "aborted"):
                    raise ServiceError(
                        409,
                        f"dkg session {dkg_id!r} round {current} is "
                        "terminal",
                    )
                new_round = {
                    "round": round_no,
                    "nodes": [],
                    "commits": {},
                    "shared": {},
                    "state": "aborted",
                }
            else:  # replace
                if state not in ("commit", "share"):
                    raise ServiceError(
                        409,
                        "replace requires the current round to be in "
                        "the commit or share stage",
                    )
                node_ids = [n for n, _ in current_round["nodes"]]
                if node not in node_ids:
                    raise ServiceError(
                        409,
                        f"node {node!r} is not active in the "
                        "current round",
                    )
                if replacement in node_ids:
                    raise ServiceError(
                        409,
                        f"replacement {replacement!r} is not free",
                    )
                new_round = {
                    "round": round_no,
                    "nodes": [
                        (replacement, key) if n == node else (n, k)
                        for n, k in current_round["nodes"]
                    ],
                    "commits": {},
                    "shared": {},
                    "state": "commit",
                }
            # 首次提交：应用轮次派生并以 dkg_failover 事件为唯一
            # 提交点（在跨进程事务锁内追加；事件之外无任何状态落盘，
            # 崩溃后由事件序列重建，无需回滚）。
            session["rounds"][round_no] = new_round
            session["current"] = round_no
            session["failovers"][round_no] = {
                "action": action,
                "node": node,
                "replacement": replacement,
                "key": key,
            }
            self._emit(
                wallet_id,
                self._audit_event(
                    audit.TYPE_DKG_FAILOVER,
                    request_id=f"{dkg_id}/{round_no}",
                    details={
                        "id": dkg_id,
                        "round": round_no,
                        "action": action,
                        "node": node,
                        "replacement": replacement,
                        "key": key,
                        "state": new_round["state"],
                    },
                ),
            )
            return 201, self._dkg_view(session, round_no)
    except CorruptDataError:
        raise
    except ValueError:
        # wallet_id 含非法字符（构造锁路径时抛出）
        raise ServiceError(400, "invalid wallet_id")

"""钱包审计事件存储（仅追加）。

磁盘布局（data_dir 下）::

    audit/<wallet_id>.json   该钱包的审计事件日志（seq 从 1 起单调递增）

文件形如::

    {"wallet_id": "w1",
     "next_seq": 4,
     "events": [
       {"seq": 1, "type": "policy_updated", "at": "...Z",
        "request_id": null, "actor_id": null,
        "reason": null, "details": {...}},
       ...
     ]}

关键性质：
- seq 从 1 开始，写入后立即持久化；服务重启后续写，seq 接续文件中的
  next_seq（也兼容仅依据末尾事件 seq 推断的旧文件）；
- 仅追加：只在 events 末尾追加，从不修改/删除历史事件；
- 写入采用同目录临时文件 + os.replace 原子替换；
- 调用方（service）在同一把每钱包事务锁内完成"状态变更 + 事件追加"，
  事件追加失败时回滚状态，保证状态与事件原子。
"""

from __future__ import annotations

import json
import os
import tempfile
import threading
from typing import Optional

from .store import (
    CorruptDataError,
    WalletStore,
    _check_id,
    _SAFE_ID,
    parse_utc_iso,
)


def _safe_id_match(value: str) -> bool:
    return bool(_SAFE_ID.match(value))

#: 审计事件类型
TYPE_POLICY_UPDATED = "policy_updated"
TYPE_REQUEST_CREATED = "request_created"
TYPE_REQUEST_APPROVED = "request_approved"
TYPE_REQUEST_REJECTED = "request_rejected"
TYPE_REQUEST_EXPIRED = "request_expired"
TYPE_REQUEST_SIGNED = "request_signed"
TYPE_SHARE_ROTATION_PREPARED = "share_rotation_prepared"
TYPE_SHARE_ROTATION_ACTIVATED = "share_rotation_activated"
TYPE_ASSET_OPERATION_COMMITTED = "asset_operation_committed"
TYPE_TRANSACTION_POLICY_UPDATED = "transaction_policy_updated"
TYPE_SESSION_EVENT = "session_event"
TYPE_SESSION_PARTICIPANT_REPLACED = "session_participant_replaced"
TYPE_SESSION_TAKEOVER = "session_takeover"
TYPE_DKG_STAGE = "dkg_stage"
TYPE_DKG_FAILOVER = "dkg_failover"
TYPE_DKG_FAILOVER_POLICY_UPDATED = "dkg_failover_policy_updated"
TYPE_CHAIN_POLICY = "chain_policy"
TYPE_CHAIN_REPORT = "chain_report"
TYPE_CHAIN_ARBITRATION = "chain_arbitration"
TYPE_CHAIN_VOTE = "chain_vote"

#: 单字母缩写 -> 完整类型（P/C/A/R/E/S）
EVENT_TYPES = {
    "P": TYPE_POLICY_UPDATED,
    "C": TYPE_REQUEST_CREATED,
    "A": TYPE_REQUEST_APPROVED,
    "R": TYPE_REQUEST_REJECTED,
    "E": TYPE_REQUEST_EXPIRED,
    "S": TYPE_REQUEST_SIGNED,
}

#: details 键序须按 README 既定顺序在落盘/查询/灾备保序的事件类型。
#: 其余事件类型的 details 仍按 sort_keys 规范序落盘（行为不变）。
_DETAILS_KEY_ORDER = {
    TYPE_SESSION_PARTICIPANT_REPLACED: (
        "session_id",
        "old_share_id",
        "new_share_id",
    ),
    TYPE_SESSION_TAKEOVER: (
        "takeover_id",
        "stage",
        "old_share_id",
        "new_share_id",
    ),
    TYPE_DKG_STAGE: (
        "id",
        "op",
        "node",
        "key",
        "hash",
        "peer",
        "state",
    ),
    TYPE_DKG_FAILOVER: (
        "id",
        "round",
        "action",
        "node",
        "replacement",
        "key",
        "state",
    ),
    TYPE_CHAIN_POLICY: (
        "chain_id",
        "enabled",
        "required_confirmations",
        "reorg_window",
    ),
    TYPE_CHAIN_REPORT: (
        "chain_id",
        "tx_id",
        "block_height",
        "block_hash",
        "confirmations",
    ),
    TYPE_CHAIN_ARBITRATION: (
        # 合法旧链策略事件：仅只读兼容（新 PUT 不再写此类型）
        "sources",
        "quorum",
    ),
    # chain_vote 事件承担两种语义，按 details 的**精确键集**区分：
    # 多源仲裁策略（request_id 为资产标识）用 {sources,quorum}；
    # 观察票（request_id 为资产操作标识）用 {source,report,state}。
    TYPE_CHAIN_VOTE: (
        ("sources", "quorum"),
        ("source", "report", "state"),
    ),
}


def _order_event_details(event: dict) -> None:
    """把既定事件类型的 details 就地重排为 README 既定键序。

    仅当 details 键集与既定键序恰好一致时重排；键集不符的现场留给各
    语义对账路径 fail-closed，绝不在这里猜写。chain_vote 事件按精确
    键集在策略序 {sources,quorum} 与票序 {source,report,state} 间选择
    （两种语义共用同一事件类型）。
    """
    order = _DETAILS_KEY_ORDER.get(event.get("type"))
    details = event.get("details")
    if order is None or not isinstance(details, dict):
        return
    if order and isinstance(order[0], tuple):
        matched = next(
            (candidate for candidate in order if set(details) == set(candidate)),
            None,
        )
        if matched is None:
            return
        event["details"] = {key: details[key] for key in matched}
        return
    if set(details) != set(order):
        return
    event["details"] = {key: details[key] for key in order}


def _canonicalize_sorted(value: object) -> object:
    """递归重排为 sort_keys 规范序（与 WalletStore._atomic_write 同字节）。"""
    if isinstance(value, dict):
        return {k: _canonicalize_sorted(value[k]) for k in sorted(value)}
    if isinstance(value, list):
        return [_canonicalize_sorted(item) for item in value]
    return value


def _canonical_event(event: object) -> object:
    """单条事件的落盘规范形：七字段 sort_keys，惟既定类型 details 保序。"""
    if not isinstance(event, dict):
        return _canonicalize_sorted(event)
    canonical = {}
    for key in sorted(event):
        value = event[key]
        if (
            key == "details"
            and event.get("type") in _DETAILS_KEY_ORDER
            and isinstance(value, dict)
        ):
            # 保留构造/读取时已归一为 README 既定顺序的 details 键序
            canonical[key] = value
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _canonical_log(data: dict) -> dict:
    """审计日志整体落盘规范形（顶层与各事件 sort_keys，既定 details 保序）。"""
    canonical = {}
    for key in sorted(data):
        value = data[key]
        if key == "events" and isinstance(value, list):
            canonical[key] = [_canonical_event(event) for event in value]
        else:
            canonical[key] = _canonicalize_sorted(value)
    return canonical


def _atomic_write_log(path: str, data: dict) -> None:
    """与 WalletStore._atomic_write 相同的临时文件 + 原子替换；序列化按
    _canonical_log（既定事件类型的 details 按 README 既定键序落盘）。"""
    directory = os.path.dirname(path)
    os.makedirs(directory, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=directory, prefix=".tmp-", suffix=".json")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(_canonical_log(data), f, ensure_ascii=False, indent=2)
            f.write("\n")
        os.replace(tmp_path, path)
    except BaseException:
        try:
            os.unlink(tmp_path)
        except FileNotFoundError:
            pass
        raise


class AuditStore:
    """审计事件日志的仅追加文件存储（一个钱包一个文件）。"""

    def __init__(self, data_dir: str) -> None:
        self._data_dir = data_dir
        self._audit_dir = os.path.join(data_dir, "audit")
        self._lock = threading.Lock()

    def _path(self, wallet_id: str) -> str:
        _check_id("wallet_id", wallet_id)
        return os.path.join(self._audit_dir, wallet_id + ".json")

    @staticmethod
    def _event_shape_ok(event: object) -> bool:
        """单条审计事件的严格形状：

        seq 为非布尔正整数；type 为非空字符串；at 为可解析的 UTC 时间；
        request_id/actor_id/reason 为 null 或字符串；details 为对象。
        details 内部各事件类型的语义由相应恢复路径（轮换链/会话动作序列/
        账本对账）负责，全局加载不重复解释。"""
        if not isinstance(event, dict):
            return False
        seq = event.get("seq")
        if not isinstance(seq, int) or isinstance(seq, bool) or seq < 1:
            return False
        if not isinstance(event.get("type"), str) or not event["type"]:
            return False
        if parse_utc_iso(event.get("at")) is None:
            return False
        for key in ("request_id", "actor_id", "reason"):
            value = event.get(key)
            if value is not None and not isinstance(value, str):
                return False
        if not isinstance(event.get("details"), dict):
            return False
        return True

    def _read_strict(self, wallet_id: str) -> Optional[dict]:
        """读取并严格校验审计文件；文件不存在返回 None。

        以下现场一律视为不可对账的数据损坏（CorruptDataError），绝不静默
        归一为空日志后覆盖历史：JSON 不可解析、顶层不是对象、events 缺失
        或不是列表、wallet_id 字段不匹配、任一事件形状非法、seq 不从 1
        起 / 不连续 / 有重号、记录的 next_seq 与实际最大 seq 矛盾。
        """
        path = self._path(wallet_id)
        data = WalletStore._read_json(path)
        if data is None:
            return None
        if not isinstance(data, dict):
            raise CorruptDataError(
                f"audit log {path!r} top-level value is not an object"
            )
        recorded_wallet = data.get("wallet_id")
        if recorded_wallet is not None and recorded_wallet != wallet_id:
            raise CorruptDataError(
                f"audit log {path!r} wallet_id {recorded_wallet!r} does not "
                f"match its file name {wallet_id!r}"
            )
        events = data.get("events")
        if "events" not in data or not isinstance(events, list):
            raise CorruptDataError(
                f"audit log {path!r} has no list-valued 'events'"
            )
        seqs: list[int] = []
        for event in events:
            if not self._event_shape_ok(event):
                raise CorruptDataError(
                    f"audit log {path!r} has a malformed event"
                )
            seqs.append(event["seq"])
        # seq 必须恰为 1..N：不重号、不缺口、单调（物理顺序允许被外部重排，
        # 查询始终按 seq 升序；但 seq 集合本身必须连续）。
        if sorted(seqs) != list(range(1, len(seqs) + 1)):
            raise CorruptDataError(
                f"audit log {path!r} has a non-contiguous or duplicated seq"
            )
        stored_next = data.get("next_seq")
        if stored_next is not None:
            if (
                not isinstance(stored_next, int)
                or isinstance(stored_next, bool)
                or stored_next != len(events) + 1
            ):
                raise CorruptDataError(
                    f"audit log {path!r} next_seq disagrees with its events"
                )
        # 既定事件类型的 details 在内存视图中归一为 README 既定键序，
        # 使查询/重建/重写（落盘与灾备）都按该顺序保序。
        for event in events:
            _order_event_details(event)
        return data

    def check_log(self, wallet_id: str) -> None:
        """只读严格校验审计文件；损坏抛 CorruptDataError/OSError。
        文件不存在（尚无事件）视为正常空状态。"""
        _check_id("wallet_id", wallet_id)
        self._read_strict(wallet_id)

    def list_audit_wallet_ids(self) -> list[str]:
        """返回存在审计文件的全部 wallet_id（启动恢复扫描用）。"""
        try:
            names = os.listdir(self._audit_dir)
        except FileNotFoundError:
            return []
        return sorted(
            name[: -len(".json")]
            for name in names
            if name.endswith(".json")
            and _safe_id_match(name[: -len(".json")])
        )

    def _read(self, wallet_id: str) -> Optional[dict]:
        return self._read_strict(wallet_id)

    def append_event(self, wallet_id: str, event: dict) -> dict:
        """原子追加一条事件，分配下一个 seq 并持久化，返回含 seq/at 的记录。

        seq 从 1 起；同一 wallet 的写入在此串行化。调用方负责在更大的
        每钱包事务锁内把状态变更与本调用绑定（失败时回滚状态）。

        既有日志损坏 / seq 矛盾时抛 CorruptDataError，绝不把历史清空后
        继续写（那会用一条新事件覆盖全部审计历史）。
        """
        return self.append_events(wallet_id, [event])[0]

    def append_events(self, wallet_id: str, events: list[dict]) -> list[dict]:
        """原子追加一批事件：一次落盘分配连续 seq（n、n+1、…），返回含
        seq/at 的记录列表。

        整批要么全部持久化、要么全部不持久化（同目录临时文件 +
        os.replace 原子替换）：多条事件构成同一提交点（如达门槛
        chain_report 与紧邻的 asset_operation_committed）时使用，崩溃
        窗口内绝不出现只落前半截的日志，也不留 seq 缺口。

        语义与单条追加相同：严格加载既有日志（损坏 / seq 矛盾抛
        CorruptDataError，绝不清空历史后续写），seq 从 1 起连续分配；
        调用方负责在每钱包事务锁内把状态变更与本调用绑定。
        """
        if not events:
            raise ValueError("events must be a non-empty list")
        path = self._path(wallet_id)
        with self._lock:
            data = self._read_strict(wallet_id)
            if data is None:
                data = {"wallet_id": wallet_id, "next_seq": 1, "events": []}
            existing = data["events"]
            # 严格加载已保证 1..N 连续：下一个 seq 直接取 N+1，
            # 与 next_seq（兼容缺字段的旧文件）一致。
            next_seq = len(existing) + 1
            stamped_events = []
            for event in events:
                stamped = dict(event)
                stamped["seq"] = next_seq
                # 既定事件类型的 details 落盘前归一为 README 既定键序
                _order_event_details(stamped)
                existing.append(stamped)
                stamped_events.append(stamped)
                next_seq += 1
            data["next_seq"] = next_seq
            _atomic_write_log(path, data)
            return stamped_events

    def find_event_by_request(
        self,
        wallet_id: str,
        event_type: str,
        request_id: str,
    ) -> Optional[dict]:
        """按 (类型, request_id) 查找一条已持久化事件，不存在返回 None。

        启动恢复据此判定崩溃前的资产提交事务是否已把事件落盘：事件在
        则补齐账本，事件不在则回滚为 pending。纯只读，不分配 seq。
        """
        data = self._read(wallet_id)
        if not data:
            return None
        for event in data.get("events", []):
            if (
                isinstance(event, dict)
                and event.get("type") == event_type
                and event.get("request_id") == request_id
            ):
                return dict(event)
        return None

    def find_session_event(
        self, wallet_id: str, request_id: str, action: str
    ) -> Optional[dict]:
        """按 (request_id, details.action) 查找一条 session_event。

        签名会话崩溃恢复据此判定创建/签名是否已提交：事件在则状态不可
        撤回（前滚），事件不在则回滚。纯只读，不分配 seq。
        """
        for event in self.session_events(wallet_id).get(request_id, []):
            details = event.get("details")
            if isinstance(details, dict) and details.get("action") == action:
                return dict(event)
        return None

    def session_events(self, wallet_id: str) -> dict[str, list[dict]]:
        """返回该钱包全部 session_event，按 request_id（会话 id）分组。

        签名会话崩溃恢复一次性读取审计文件，据此判定每个会话哪些动作
        （created/share_received/expired/signed）已经提交。纯只读。"""
        data = self._read(wallet_id)
        result: dict[str, list[dict]] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != TYPE_SESSION_EVENT:
                continue
            request_id = event.get("request_id")
            if isinstance(request_id, str):
                result.setdefault(request_id, []).append(dict(event))
        return result

    def _events_grouped_by_request(
        self, wallet_id: str, event_type: str
    ) -> dict[str, list[dict]]:
        """返回该钱包指定类型的全部事件，按 request_id 分组，组内按 seq
        升序。纯只读，不分配 seq。"""
        data = self._read(wallet_id)
        result: dict[str, list[dict]] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != event_type:
                continue
            request_id = event.get("request_id")
            if isinstance(request_id, str):
                result.setdefault(request_id, []).append(dict(event))
        for events in result.values():
            events.sort(key=lambda e: e.get("seq", 0))
        return result

    def session_participant_replaced_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 session_participant_replaced 事件，按 request_id
        （会话 id）分组，组内按 seq 升序。

        会话参与者替换的崩溃恢复与幂等重放据此判定哪些替换已经提交
        （事件在则替换不可撤回）。纯只读，不分配 seq。"""
        return self._events_grouped_by_request(
            wallet_id, TYPE_SESSION_PARTICIPANT_REPLACED
        )

    def session_takeover_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 session_takeover 事件，按 request_id（会话 id）
        分组，组内按 seq 升序。

        两阶段参与者接管的崩溃恢复与幂等重放据此判定各阶段是否已提交
        （事件在则该阶段不可撤回）。纯只读，不分配 seq。"""
        return self._events_grouped_by_request(
            wallet_id, TYPE_SESSION_TAKEOVER
        )

    def dkg_stage_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 dkg_stage 事件，按 request_id（DKG 会话 id）
        分组，组内按 seq 升序。

        DKG 会话状态仅由这些事件持久化（事件是唯一提交点）：在线处理与
        崩溃恢复据此重建各会话的 register/commit/share 推进序列。
        纯只读，不分配 seq。"""
        return self._events_grouped_by_request(wallet_id, TYPE_DKG_STAGE)

    def dkg_failover_events(
        self, wallet_id: str
    ) -> dict[str, list[dict]]:
        """返回该钱包全部 dkg_failover 事件，按 request_id（``<会话id>/<轮次>``）
        分组，组内按 seq 升序。

        DKG 故障轮次仅由这些事件持久化（事件是唯一提交点）：在线处理与
        崩溃恢复据此重建各会话的轮次链（abort/replace 派生序列）。
        纯只读，不分配 seq。"""
        return self._events_grouped_by_request(wallet_id, TYPE_DKG_FAILOVER)

    def activated_rotation_events(self, wallet_id: str) -> dict[str, dict]:
        """返回该钱包已落盘的 share_rotation_activated 事件映射
        ``{rotation_id: event}``。

        启动/运行时轮换恢复据此判定激活是否已提交（事件在则前滚为
        active，事件不在则回滚 prepared）。每个 rotation 至多一条激活事件；
        同一 rotation_id 出现两条激活事件属于不可对账的重复提交点，抛
        CorruptDataError（fail-closed），绝不任取一条。纯只读。
        """
        return self._rotation_events(
            wallet_id, TYPE_SHARE_ROTATION_ACTIVATED, "activated"
        )

    def prepared_rotation_events(self, wallet_id: str) -> dict[str, dict]:
        """返回该钱包已落盘的 share_rotation_prepared 事件映射
        ``{rotation_id: event}``。

        恢复据此判定轮换首次准备是否已提交（事件在则 prepared 记录合法；
        记录在但准备事件缺失说明记录是崩溃窗口残留）。准备记录在暂存
        失效被安全删除后允许以同 rotation_id 重新准备，因此同一 id 可能
        有多条准备事件，这里以最后一条为准、不报错；真正唯一的提交点是
        share_rotation_activated。纯只读。
        """
        return self._rotation_events(
            wallet_id, TYPE_SHARE_ROTATION_PREPARED, "prepared",
            strict_unique=False,
        )

    def _rotation_events(
        self,
        wallet_id: str,
        event_type: str,
        kind: str,
        strict_unique: bool = True,
    ) -> dict[str, dict]:
        data = self._read(wallet_id)
        result: dict[str, dict] = {}
        if not data:
            return result
        for event in data.get("events", []):
            if not isinstance(event, dict):
                continue
            if event.get("type") != event_type:
                continue
            details = event.get("details")
            rotation_id = (
                details.get("rotation_id")
                if isinstance(details, dict)
                else None
            )
            if not isinstance(rotation_id, str):
                raise CorruptDataError(
                    f"audit log for wallet {wallet_id!r} has a share rotation "
                    f"{kind} event without a rotation_id"
                )
            if strict_unique and rotation_id in result:
                raise CorruptDataError(
                    f"audit log for wallet {wallet_id!r} has multiple share "
                    f"rotation {kind} events for {rotation_id!r}"
                )
            # 非唯一（prepared）：保留 seq 最大的一条
            existing = result.get(rotation_id)
            if existing is None or (
                isinstance(event.get("seq"), int)
                and (
                    not isinstance(existing.get("seq"), int)
                    or event["seq"] > existing["seq"]
                )
            ):
                result[rotation_id] = dict(event)
        return result

    def list_events(
        self, wallet_id: str, from_seq: int = 1, limit: int = 1000
    ) -> list[dict]:
        """按 seq 升序返回 seq >= from_seq 的至多 limit 条事件。

        无日志文件或范围内无事件时返回 []。返回的是记录副本，
        调用方修改不会影响存储内容。日志损坏抛 CorruptDataError
        （由调用方 fail-closed），绝不静默返回残缺历史。
        """
        data = self._read(wallet_id)
        if not data:
            return []
        # 严格加载已保证 seq 集合为 1..N；仍按 seq 升序输出，避免外部改动
        # 事件物理顺序影响公开响应。
        events = [
            dict(event)
            for event in data["events"]
            if event["seq"] >= from_seq
        ]
        events.sort(key=lambda e: e["seq"])
        return events[:limit]

    def events_by_type(self, wallet_id: str, event_type: str) -> list[dict]:
        """返回某类型的全部事件（按 seq 升序，返回副本）。纯只读。

        账本语义恢复据此与已提交操作做双向对账：committed 事件必须与
        账本一一对应。日志损坏抛 CorruptDataError（fail-closed）。"""
        data = self._read(wallet_id)
        if not data:
            return []
        return [
            dict(event)
            for event in sorted(data["events"], key=lambda e: e["seq"])
            if event.get("type") == event_type
        ]

    def all_events(self, wallet_id: str) -> list[dict]:
        """返回该钱包全部事件（按 seq 升序，返回副本）。纯只读。

        跨类型对账（如链确认报告与资产提交事件的紧邻关系）据此按 seq
        顺序重放全部事件。日志损坏抛 CorruptDataError（fail-closed）。"""
        data = self._read(wallet_id)
        if not data:
            return []
        return [
            dict(event)
            for event in sorted(data["events"], key=lambda e: e["seq"])
        ]

        raise RecoveryError(
            f"wallet {wallet_id!r} cannot be reconciled: {exc}"
        ) from exc

@staticmethod
def _audit_event(
    event_type: str,
    request_id=None,
    actor_id=None,
    reason=None,
    details=None,
) -> dict:
    """构造审计事件（seq 由 AuditStore 分配）。"""
    return {
        "type": event_type,
        "at": _utc_now_iso(),
        "request_id": request_id,
        "actor_id": actor_id,
        "reason": reason,
        "details": details,
    }

def _emit(self, wallet_id: str, event: dict) -> None:
    self._audit.append_event(wallet_id, event)

# ---- 建钱包 ---------------------------------------------------------

def create_wallet(self, wallet_id: object, shares: object) -> dict:
    if not isinstance(wallet_id, str) or not wallet_id:
        raise ServiceError(400, "wallet_id must be a non-empty string")
    # bool 是 int 的子类，必须先排除；2.0 == 2，必须要求真正的 int
    if not isinstance(shares, int) or isinstance(shares, bool):
        raise ServiceError(400, "shares must equal 2")
    if shares != REQUIRED_SHARES:
        raise ServiceError(400, "shares must equal 2")
    try:
        share_keys = [crypto.generate_share_key(sid) for sid in SHARE_IDS]
        # 跨进程防重：同一 data-dir 上多个服务进程并发建同名钱包时，
        # 只有一个能在事务锁内提交成功
        with self._wallet_lock(wallet_id):
            self._store.create_wallet(
                wallet_id, share_keys, _utc_now_iso()
            )
    except DuplicateWalletError:
        raise ServiceError(409, f"wallet {wallet_id!r} already exists")
    except ValueError:
        # wallet_id 含非法字符
        raise ServiceError(400, "invalid wallet_id")
    public_key = crypto.combine_public_keys(
        [k.public_bytes for k in share_keys]
    )
    return {
        "wallet_id": wallet_id,
        "public_key": public_key.hex(),
        "share_ids": list(SHARE_IDS),
    }

# ---- 查询钱包 -------------------------------------------------------

def get_wallet(self, wallet_id: str) -> dict:
    try:
        with self._wallet_lock(wallet_id):
            # 查询前先自愈他进程崩溃遗留的激活现场，绝不把换了一半
            # 的公钥/份额经 GET 暴露出去
            self._heal_wallet(wallet_id)
            record = self._store.get_wallet(wallet_id)
    except CorruptDataError:
        # 钱包元数据损坏：fail-closed（由 HTTP 边界转 503）
        raise
    except ValueError:
        raise ServiceError(400, "invalid wallet_id")
    if record is None:
        raise ServiceError(404, f"wallet {wallet_id!r} not found")
    return {
        "wallet_id": record["wallet_id"],
        "public_key": record["public_key"],
        "created_at": record["created_at"],
    }

