            svc2.get_dkg_nodes("w1"),
            {"nodes": {
                "n1": {"key": KEY_A, "state": "up"},
                "n2": {"key": KEY_B, "state": "down"},
                "n3": {"key": KEY_C, "state": "up"},
            }},
        )
        code, got = _call(
            svc2.post_dkg_failover,
            "w1", "d1", 2, "replace", "n2", None, None,
        )
        self.assertEqual(code, 200)
        self.assertEqual(got, view)


